import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/31-Unity_SDK_Design.html","title":"Unity SDK 设计与接口规范","lang":"en-US","frontmatter":{},"filePathRelative":"31-Unity_SDK_Design.md","git":{"createdTime":1765123100000,"updatedTime":1765123100000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`31-Unity_SDK_Design.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="unity-sdk-设计与接口规范" tabindex="-1"><a class="header-anchor" href="#unity-sdk-设计与接口规范"><span>Unity SDK 设计与接口规范</span></a></h1><blockquote><p>目的：在 NetCore 与 API 规范的基础上，定义 Unity/U3D 客户端 SDK 的模块划分、公共 API、事件、调试工具与资源管理接口，确保客户端团队能够快速接入，并与服务器协议保持一致。</p></blockquote><h2 id="_1-模块结构" tabindex="-1"><a class="header-anchor" href="#_1-模块结构"><span>1. 模块结构</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ApolloSDK (Unity Package)</span>
<span class="line"> ├─ Network</span>
<span class="line"> │    ├─ ApolloClient (TCP/KCP/WebSocket)</span>
<span class="line"> │    ├─ ConnectionConfig / RetryPolicy</span>
<span class="line"> │    ├─ PacketEncoder / Decoder</span>
<span class="line"> │    └─ HeartbeatManager</span>
<span class="line"> ├─ Messaging</span>
<span class="line"> │    ├─ MessageRouter</span>
<span class="line"> │    ├─ ProtobufSerializer (Generated via protoc)</span>
<span class="line"> │    └─ HandlerRegistry</span>
<span class="line"> ├─ Session</span>
<span class="line"> │    ├─ AuthManager (token 登录)</span>
<span class="line"> │    ├─ SessionStore (重连)</span>
<span class="line"> │    └─ MetricsCollector</span>
<span class="line"> ├─ Resource</span>
<span class="line"> │    ├─ PatchManager (引用 docs/26)</span>
<span class="line"> │    ├─ ManifestLoader</span>
<span class="line"> │    └─ Storage (cache)</span>
<span class="line"> ├─ Utilities</span>
<span class="line"> │    ├─ Logger</span>
<span class="line"> │    ├─ Diagnostics (抓包/日志上报)</span>
<span class="line"> │    └─ Config (热更新配置)</span>
<span class="line"> └─ Samples / Editor Tools</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-初始化流程" tabindex="-1"><a class="header-anchor" href="#_2-初始化流程"><span>2. 初始化流程</span></a></h2><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code class="language-csharp"><span class="line"><span class="token class-name"><span class="token keyword">var</span></span> config <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ApolloClientConfig</span> <span class="token punctuation">{</span></span>
<span class="line">    ServerAddress <span class="token operator">=</span> <span class="token string">&quot;game.example.com&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    Port <span class="token operator">=</span> <span class="token number">7700</span><span class="token punctuation">,</span></span>
<span class="line">    Protocol <span class="token operator">=</span> TransportProtocol<span class="token punctuation">.</span>Tcp<span class="token punctuation">,</span></span>
<span class="line">    HeartbeatInterval <span class="token operator">=</span> TimeSpan<span class="token punctuation">.</span><span class="token function">FromSeconds</span><span class="token punctuation">(</span><span class="token number">15</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Encryption <span class="token operator">=</span> EncryptionMode<span class="token punctuation">.</span>Aes256<span class="token punctuation">,</span></span>
<span class="line">    ResourceSlot <span class="token operator">=</span> <span class="token string">&quot;A&quot;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token class-name"><span class="token keyword">var</span></span> client <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">ApolloClient</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span><span class="token function">RegisterHandler</span><span class="token punctuation">(</span>PlayerMove<span class="token punctuation">.</span>MsgId<span class="token punctuation">,</span> OnPlayerMove<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span>OnConnected <span class="token operator">+=</span> HandleConnected<span class="token punctuation">;</span></span>
<span class="line">client<span class="token punctuation">.</span>OnDisconnected <span class="token operator">+=</span> HandleDisconnected<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">await</span> client<span class="token punctuation">.</span><span class="token function">ConnectAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">await</span> client<span class="token punctuation">.</span><span class="token function">LoginAsync</span><span class="token punctuation">(</span>loginRequest<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 自动走 AuthManager</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-核心-api" tabindex="-1"><a class="header-anchor" href="#_3-核心-api"><span>3. 核心 API</span></a></h2><h3 id="_3-1-apolloclient" tabindex="-1"><a class="header-anchor" href="#_3-1-apolloclient"><span>3.1 ApolloClient</span></a></h3><table><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>Task ConnectAsync()</code></td><td>建立连接（支持 TCP/KCP/WebSocket）。</td></tr><tr><td><code>Task DisconnectAsync()</code></td><td>主动断开。</td></tr><tr><td><code>Task SendAsync&lt;T&gt;(ushort msgId, T message)</code></td><td>序列化并发送 Protobuf 消息。</td></tr><tr><td><code>void RegisterHandler(ushort msgId, Action&lt;T&gt; handler)</code></td><td>注册消息处理。</td></tr><tr><td><code>void UnregisterHandler(ushort msgId)</code></td><td>移除处理器。</td></tr><tr><td><code>event Action Connected/Disconnected/HeartbeatTimeout</code></td><td>连接事件。</td></tr></tbody></table><h3 id="_3-2-authmanager" tabindex="-1"><a class="header-anchor" href="#_3-2-authmanager"><span>3.2 AuthManager</span></a></h3><table><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>Task&lt;LoginResponse&gt; LoginAsync(LoginRequest request)</code></td><td>登录并建立会话。</td></tr><tr><td><code>Task&lt;TokenRefreshResponse&gt; RefreshTokenAsync()</code></td><td>刷新凭证。</td></tr><tr><td><code>Task LogoutAsync()</code></td><td>主动登出。</td></tr></tbody></table><h3 id="_3-3-patchmanager" tabindex="-1"><a class="header-anchor" href="#_3-3-patchmanager"><span>3.3 PatchManager</span></a></h3><p>参见 <code>docs/26</code>：提供 <code>CheckUpdate()</code>, <code>DownloadAsync()</code>, <code>GetBundle(string name)</code> 等接口，支持灰度。</p><h2 id="_4-消息路由与-protobuf" tabindex="-1"><a class="header-anchor" href="#_4-消息路由与-protobuf"><span>4. 消息路由与 Protobuf</span></a></h2><ul><li>使用 <code>protoc</code> + <code>grpc_csharp_plugin</code> 生成 C# Protobuf 类，生成脚本由 build pipeline 自动运行。</li><li>消息 ID/枚举来自 <code>docs/22</code> 的统一配置；SDK 在构建时引入生成文件（<code>MessageId.cs</code>）。</li><li><code>MessageRouter</code> 维护 <code>Dictionary&lt;ushort, IMessageHandler&gt;</code>，处理多线程上下文问题（Unity 主线程 vs 网络线程）。</li></ul><h2 id="_5-连接与重连策略" tabindex="-1"><a class="header-anchor" href="#_5-连接与重连策略"><span>5. 连接与重连策略</span></a></h2><ul><li><code>RetryPolicy</code> 可配置最大重连次数/间隔；支持指数退避。</li><li>重连时携带 <code>session_token</code> 与最后 ack seq，服务器根据 NetCore 去重逻辑恢复。</li><li>若超过重连次数，触发 <code>Disconnected</code> 事件，UI 提示。</li></ul><h2 id="_6-安全" tabindex="-1"><a class="header-anchor" href="#_6-安全"><span>6. 安全</span></a></h2><ul><li>SDK 内置 AES/ChaCha 加密模块；握手阶段接收服务器返回的密钥/IV。</li><li>包头包含 HMAC；SDK 自动计算。</li><li>资源 Manifest 验证签名，防篡改。</li></ul><h2 id="_7-调试与诊断" tabindex="-1"><a class="header-anchor" href="#_7-调试与诊断"><span>7. 调试与诊断</span></a></h2><ul><li>Logger：提供多级别日志，支持写入文件/上传服务器（可配置）。</li><li>Diagnostics：可启用抓包模式（记录最近 N 条消息）用于问题排查。</li><li>提供 Unity Editor 工具窗口（<code>Window -&gt; Apollo SDK Diagnostics</code>）：显示连接状态、心跳、延迟、消息统计。</li><li>支持在 Editor 模式下模拟网络状况（延迟、丢包），调用 NetCore 调试接口。</li></ul><h2 id="_8-示例与文档" tabindex="-1"><a class="header-anchor" href="#_8-示例与文档"><span>8. 示例与文档</span></a></h2><ul><li>包含 <code>Samples</code> 目录：示例项目演示登录、移动、战斗、资源更新流程。</li><li>文档（Markdown/HTML）：安装、API 参考、常见问题、错误码（对应服务器 <code>StatusCode</code>）。</li><li>提供 CI pipeline（Unity 构建 + 测试）以验证 SDK。</li></ul><h2 id="_9-发布与版本" tabindex="-1"><a class="header-anchor" href="#_9-发布与版本"><span>9. 发布与版本</span></a></h2><ul><li>SDK 采用 SemVer；与服务器版本通过 <code>sdk_version</code> 字段校验。</li><li>发布形式：Unity Package（UPM）和 <code>.unitypackage</code>。</li><li>提供 Release Note，说明兼容服务器版本、变更项。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>实现核心网络层（TCP/KCP/心跳/重连），与 NetCore 对接。</li><li>集成 Auth/Patch/Resource 模块。</li><li>打通示例场景，完成自动化测试。</li><li>发布 1.0 内测版，与服务器联调；收集问题迭代。</li><li>提供 CLI/编辑器工具、诊断日志系统。</li></ol><hr><p>该文档为 Unity 客户端团队提供明确的 SDK 接入蓝图，确保与服务器协议、配置、资源体系保持一致。***</p>`,29)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};